import * as signalR from '@microsoft/signalr';
import { getFreshAccessToken } from './auth/tokenProvider';

const connection = new signalR.HubConnectionBuilder()
  .withUrl('/hubs/projects', {
    accessTokenFactory: async () => await getFreshAccessToken()
  })
  .withAutomaticReconnect()
  .build();

connection.on('ProjectUpdated', payload => {
  console.info('project updated', payload.projectId);
});

connection.onclose(error => {
  console.error('projects hub closed', error?.message, connection.connectionId);
});

export async function startProjectHub(projectId: string): Promise<void> {
  await connection.start();
  await connection.invoke('SubscribeToProject', projectId);
}

